using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchNotes>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            // Simulated web search — replace with a real search API (e.g., Bing Search)
            Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
            return query.ToLowerInvariant() switch
            {
                var q when q.Contains("quantum computing") =>
                    """
                    1. Quantum computers use qubits that can exist in superposition, enabling parallel computation.
                    2. Google achieved quantum supremacy in 2019 with their Sycamore processor (53 qubits).
                    3. IBM launched a 1,121-qubit processor (Condor) in 2023 and targets error-corrected systems by 2029.
                    4. Key applications include cryptography, drug discovery, optimization, and materials science.
                    5. Current limitations: decoherence, error rates, and extreme cooling requirements (~15 millikelvins).
                    """,
                var q when q.Contains("artificial intelligence") || q.Contains(" ai ") =>
                    """
                    1. Modern AI is primarily driven by large language models and transformer architectures.
                    2. GPT-4, Claude, and Gemini represent the frontier of general-purpose AI capabilities.
                    3. AI is being applied in healthcare, autonomous vehicles, scientific research, and creative industries.
                    4. Key challenges include alignment, hallucination, energy consumption, and job displacement concerns.
                    5. Regulatory frameworks (EU AI Act, US executive orders) are emerging globally.
                    """,
                _ =>
                    $"""
                    1. "{query}" is an active area of research with growing interest.
                    2. Multiple academic institutions and companies are publishing findings on this topic.
                    3. Recent breakthroughs suggest significant progress in the near term.
                    4. Interdisciplinary approaches combining multiple fields show promise.
                    5. Funding and investment in this area have increased substantially in recent years.
                    """
            };
        },
        "web_search",
        "Searches the web for information on a given query and returns relevant results."),

    AIFunctionFactory.Create(
        ([Description("A title or label for the note")] string title,
         [Description("The content of the note to save")] string content) =>
        {
            notes.Add(title, content);
            Console.WriteLine($"  [Tool] Saved note: \"{title}\"");
            return $"Note saved: \"{title}\" ({content.Length} chars)";
        },
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var allNotes = notes.GetAll();
            Console.WriteLine($"  [Tool] Retrieved {allNotes.Count} note(s)");
            return allNotes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", allNotes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all previously saved research notes.")
};

// Configure the agent
var agentOptions = new ChatClientAgentOptions
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for information (make multiple searches to cover different angles)
        2. Saving important findings as notes
        3. Reviewing your notes and providing a comprehensive summary

        Always search for at least 2 different aspects of the topic, save key findings as notes,
        then retrieve your notes and produce a final summary.
        """,
    MaximumIterations = 10,
    Tools = tools,
    DefaultChatOptions = new ChatOptions { Temperature = 0f, MaxOutputTokens = 2048 },
};

var agent = new ChatClientAgent(chatClient, agentOptions);

// Get topic from user
Console.Write("Enter a research topic (or press Enter for 'quantum computing'): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
    topic = "quantum computing";

Console.WriteLine($"\nResearching: {topic}\n{"".PadRight(50, '-')}");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

// Run the agent
await foreach (var message in agent.InvokeStreamingAsync(history))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.WriteLine($"\n{"".PadRight(50, '=')}\n📋 Research Summary:\n{"".PadRight(50, '=')}\n");
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine($"\n{"".PadRight(50, '-')}\nNotes collected: {notes.GetAll().Count}");
foreach (var note in notes.GetAll())
{
    Console.WriteLine($"  • {note.Title}");
}

// --- Supporting types ---

public class ResearchNotes
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));
    public List<(string Title, string Content)> GetAll() => [.. _notes];
}

