        () =>
        {
            var allNotes = notes.GetAll();
            Console.WriteLine($"  [Tool] Retrieved {allNotes.Count} note(s)");
            return allNotes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", allNotes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
